// Intended function: accumulate scan confidence deterministically while requiring callers to provide bounded nearby candidates instead of global scans.
#include "gameplay/ScanningSystem.hpp"
#include <algorithm>
namespace elysium{void ScanningSystem::upsertSignal(ScanSignal s){signals_[s.signalId]=s;}std::vector<DiscoveryRecord>ScanningSystem::pulse(const ScanPulse&p,const std::vector<std::uint64_t>&ids){std::vector<std::uint64_t>sorted=ids;std::sort(sorted.begin(),sorted.end());std::vector<DiscoveryRecord>o;for(auto id:sorted){auto i=signals_.find(id);if(i==signals_.end())continue;auto&s=i->second;float gain=std::clamp((p.power*s.strength)/(std::max(.05f,s.difficulty)),0.f,1.f);auto&d=discoveries_[s.targetStableId];if(!d.targetStableId){d.targetStableId=s.targetStableId;d.firstPulseId=p.pulseId;d.kind=s.kind;}d.confidence=std::clamp(d.confidence+gain*.35f,0.f,1.f);d.identified=d.confidence>=.8f;o.push_back(d);}return o;}std::optional<DiscoveryRecord>ScanningSystem::discovery(std::uint64_t id)const{auto i=discoveries_.find(id);return i==discoveries_.end()?std::nullopt:std::optional<DiscoveryRecord>(i->second);}}
